class Solution {
    public List<String> wordSubsets(String[] words1,String[] words2){
        int[] requirement=new int[26];
        for(String word:words2){
            int[] count=count(word);
            for(int i=0;i<26;i++)requirement[i]=Math.max(requirement[i],count[i]);
        }
        List<String> answer=new ArrayList<>();
        outer:for(String word:words1){
            int[] count=count(word);
            for(int i=0;i<26;i++)if(count[i]<requirement[i])continue outer;
            answer.add(word);
        }
        return answer;
    }
    private int[] count(String word){
        int[] result=new int[26];
        for(char c:word.toCharArray())result[c-'a']++;
        return result;
    }
}

